import fs from'node:fs/promises';import{createRequire}from'node:module';import{chromium}from'playwright-core';import{browserEnvironment,browserCandidates}from'../dist/motionBrowser.js';const require=createRequire(import.meta.url);let executablePath;for(const file of browserCandidates())try{if((await fs.stat(file)).isFile()){executablePath=file;break}}catch{}if(!executablePath)throw Error('No browser');const browser=await chromium.launch({executablePath,headless:true,chromiumSandbox:true,env:browserEnvironment()});
